const crypto = require("crypto");
const expected = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const words = ["quarterly","report","2026"];
const seps = ["-","_"," ","- "," -","__","--","-_-","-__"," _ ",  "  ","_  "];
// permutations of words order too
const perms = [ [words[0],words[1],words[2]], [words[0],words[2],words[1]], [words[1],words[0],words[2]] ];
let found = 0;
for (const p of perms) for (const s1 of seps) for (const s2 of seps) {
  const slug = p[0]+s1+p[1]+s2+p[2];
  if (!slug.includes("_2026")) continue;
  const d = crypto.createHash("sha256").update(slug,"utf8").digest("hex");
  if (d === expected) { console.log("MATCH:", JSON.stringify(slug)); found++; }
}
// case variants
for (const base of ["quarterly-report_2026","quarterly_report_2026","Quarterly-Report_2026","QUARTERLY-REPORT_2026"]) {
  const d = crypto.createHash("sha256").update(base,"utf8").digest("hex");
  if (d === expected) console.log("MATCH-CASE:", JSON.stringify(base));
}
console.log("search done, matches:", found);
'

